1468, 1567, 1589], \"page_id\": 5}], \"content\": \"<table><tr><td>FCP-VIII-1.</td><td>- Nonbanking Firms' Positions</td><td>134</td></tr><tr><td>FCP-VIII-2.</td><td>- Weekly Bank Positions</td><td>134</td></tr><tr><td>FCP-VIII-3.</td><td>- Consolidated Monthly Bank Positions</td><td>135</td></tr></table>\", \"description\": null, \"id\": 20, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [667, 1594, 1164, 1628], \"page_id\": 5}], \"content\": \"UNITED STATES DOLLAR POSITIONS ABROAD\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [262, 1630, 1567, 1746], \"page_id\": 5}], \"content\": \"<table><tr><td>FCP-IX-1.</td><td>- Nonbanking Firms' Foreign Subsidiaries' Positions</td><td>136</td></tr><tr><td>FCP-IX-2.</td><td>- Weekly Bank Foreign Office Positions</td><td>136</td></tr><tr><td>FCP-IX-3.</td><td>- Monthly Bank Foreign Office Positions</td><td>137</td></tr></table>\", \"description\": null, \"id\": 22, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [264, 95, 542, 139], \"page_id\": 6}], \"content\": \"February 1980\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1536, 100, 1565, 134], \"page_id\": 6}], \"content\": \"V\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [837, 231, 1035, 260], \"page_id\": 6}], \"content\": \"CONTENTS\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [307, 303, 1514, 334], \"page_id\": 6}], \"content\": \"FINANCIAL OPERATIONS OF GOVERNMENT AGENCIES AND FUNDS\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [786, 355, 1078, 375], \"page_id\": 6}], \"content\": \"FEDERAL CREDIT PROGRAMS\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1485, 355, 1540, 378], \"page_id\": 6}], \"content\": \"Page\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [264, 391, 1536, 856], \"page_id\": 6}], \"content\": \"<table><tr><td>GA-II-1.</td><td>- Direct Sales and Repurchases of Loans.</td><td>139</td></tr><tr><td colspan=\\\"3\\\">TRUST FUNDS</td></tr><tr><td>GA-III-1.</td><td>- Civil Service Retirement and Disability Fund.</td><td>140</td></tr><tr><td>GA-III-2.</td><td>- Federal Old-Age and Survivors Insurance Trust Fund.</td><td>141</td></tr><tr><td>GA-III-3.</td><td>- Federal Disability Insurance Trust Fund.</td><td>142</td></tr><tr><td>GA-III-4.</td><td>- Federal Hospital Insurance Trust Fund.</td><td>144</td></tr><tr><td>GA-III-5.</td><td>- Federal Supplementary Medical Insurance Trust Fund.</td><td>145</td></tr><tr><td>GA-III-6.</td><td>- Railroad Retirement Accounts.</td><td>146</td></tr><tr><td>GA-III-7.</td><td>- Unemployment Trust Fund.</td><td>147</td></tr><tr><td>GA-III-8.</td><td>- National Service Life Insurance Fund.</td><td>149</td></tr><tr><td>GA-III-9.</td><td>- Investments of Specified Trust Accounts in Public Debt Securities and Agency Securities.</td><td>150</td></tr><tr><td colspan=\\\"2\\\">Cumulative Table of Contents.</td><td>151</td></tr></table>\", \"description\": null, \"id\": 6, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [272, 1733, 1131, 1754], \"page_id\": 6}], \"content\": \"Note: Details of figures may not add to totals because of rounding.\", \"description\": null, \"id\": 7, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [274, 95, 311, 126], \"page_id\": 7}], \"content\": \"VI\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1301, 98, 1547, 129], \"page_id\": 7}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [730, 309, 1115, 332], \"page_id\": 7}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [270, 352, 507, 373], \"page_id\": 7}], \"content\": \"Auction of 2-Year Notes\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [270, 388, 869, 766], \"page_id\": 7}], \"content\": \"On January 16 the Treasury announced that it would auction $4,000 million of 2-year notes to refund $3,472 million of notes maturing January 31, 1980, and to raise $528 million new cash. The notes offered were Treasury Notes of Series N-1982, to be dated January 31, 1980, due January 31, 1982, with interest payable on July 31 and January 31 in each year until maturity. A coupon rate of 11-1/2% was set after the determination as to which tenders were accepted on a yield basis the average of which translated into an average accepted price close to 100.000.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [274, 766, 874, 1147], \"page_id\": 7}], \"content\": \"Tenders for the notes were received until 1:30 p.m., EST, January 23 and totaled $8,071 million, of which $4,006 million was accepted at yields ranging from 11.50%, price 100.000 up to 11.53%, price 99.948. Noncompetitive tenders for $1 million or less from any one bidder were accepted in full at the average yield of accepted tenders, 11.52%, price 99.965. These totaled $885 million. The $4,006 million of accepted tenders also include $315 million at the average price from Federal Reserve Banks as agents for foreign and international monetary authorities in exchange for maturing securities.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [268, 1152, 865, 1329], \"page_id\": 7}], \"content\": \"In addition to the $4,006 million of tenders accepted in the auction process, $403 million of tenders were accepted at the average price from Government accounts and Federal Reserve Banks for their own account in exchange for securities maturing January 31, 1980.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [270, 1329, 869, 1548], \"page_id\": 7}], \"content\": \"Tenders were received at Federal Reserve banks and branches and at the Bureau of the Public Debt, Washington, D. C. Bearer notes, with interest coupons attached, and notes registered as to principal and interest were authorized to be issued in denominations of $5,000, $10,000, $100,000 and $1,000,000.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [268, 1563, 452, 1587], \"page_id\": 7}], \"content\": \"February Refunding\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [268, 1607, 865, 1867], \"page_id\": 7}], \"content\": \"On January 30 the Treasury announced that it would sell to the public at auction, under competitive and noncompetitive bidding, up to $3,250 million of 3-1/2 year notes of Series J-1983, $2,000 million of 7-1/4 year notes of Series C-1987, and $2,000 million of 30-year bonds of 2005-10 to refund $4,654 million of publicly held Treasury securities maturing February 15, and to raise $2,600 million new cash.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [274, 1869, 865, 2121], \"page_id\": 7}], \"content\": \"A coupon rate of 11-7/8% was set on the notes of Series J-1983 after the determination as to which tenders were accepted on a yield basis, the average of which translated into an average accepted price close to 100.000. The notes of Series J-1983 will be dated February 15, 1980, due August 15, 1983, with interest payable semiannually on August 15 and February 15 until maturity.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [955, 391, 1555, 1067], \"page_id\": 7}], \"content\": \"Tenders for the notes of Series J-1983 were received until 1:30 p.m., EST February 5, and totaled $7,518 million of which $3,251 million was accepted at yields ranging from 11.37%, price 100.014, up to 12.00% price 99.651. Non-competitive tenders for $1 million or less were accepted in full at the average yield of accepted tenders, 11.98%, price 99.707. These totaled $675 million. In addition, $295 million of the notes were allotted at the average price to Federal Reserve Banks as agents for foreign and international monetary authorities in exchange for securities maturing February 15, 1980. A coupon rate of 12% was set on the notes of Series C-1987 after the determination as to which tenders were accepted on a yield basis, the average of which translated into an average accepted price close to 100.000. The notes of Series C-1987 will be dated February 15, 1980, due May 15, 1987, with interest payable semiannually on November 15 and May 15 until maturity.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [959, 1065, 1557, 1327], \"page_id\": 7}], \"content\": \"Tenders for the notes of Series C-1987 were received until 1:30 p.m., EST, February 6, and totaled $4,690 million, of which $2,001 million was accepted at yields ranging from 11.98%, price 99.932 up to 12.05%, price 99.599. Non-competitive tenders for $1 million or less from any one bidder were accepted in full at the average yield of accepted tenders, 12.02%, price 99.742. These totaled $324 million.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [964, 1358, 1557, 1615], \"page_id\": 7}], \"content\": \"A coupon rate of 11-3/4% was set on the bonds of 2005-10 after the determination as to which tenders were accepted on a yield basis, the average of which translated into an average accepted price close to 100.000. The bonds of 2005-10 will be dated February 15, 1980, due February 15, 2010, with interest payable semiannually on August 15 and February 15 until maturity.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [964, 1630, 1565, 1882], \"page_id\": 7}], \"content\": \"Tenders for the bonds were received until 1:30 p.m., EST, February 7 and totaled $4,635 million of which $2,001 million was accepted at yields ranging from 11.78%, price 99.754 up to 11.87%,price 99.021. Noncompetitive tenders for $1 million or less from any one bidder were accepted in full at the average yield of accepted tenders, 11.84%, price 99.264. These totaled $204 million.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [964, 1905, 1565, 2121], \"page_id\": 7}], \"content\": \"In addition to the amounts allotted to the public, $978 million of the 3-1/2 year notes, $450 million of the 7-1/4 year notes, and $644 million of the bonds were allotted to Federal Reserve Banks and Government accounts at the average prices for their own account in exchange for securities maturing February 15, 1980.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [286, 93, 507, 129], \"page_id\": 8}], \"content\": \"February 1980\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1481, 95, 1532, 126], \"page_id\": 8}], \"content\": \"VIII\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [661, 301, 1184, 332], \"page_id\": 8}], \"content\": \"Treasury Financing Operations\\u2014Continued\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [276, 373, 861, 553], \"page_id\": 8}], \"content\": \"Payment for accepted tenders in all three auctions was required to be made or completed on or before February 15, 1980, in cash, securities maturing on or before February 15, 1980, which were to be accepted at par, or other funds immediately available to the Treasury by that date.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [276, 555, 863, 877], \"page_id\": 8}], \"content\": \"Tenders were received in all of the auctions at Federal Reserve Banks and branches and at the Bureau of the Public Debt, Washington, D. C. Bearer notes and bonds, with interest coupons attached, and notes and bonds registered as to principal and interest were authorized to be issued in denominations of $1,000, $5,000, $10,000, $100,000, and $1,000,000 for the issues of 7-1/4 year notes and bonds, and $5,000, $10,000, $100,000, and $1,000,000 for the issue of 3-1/2 year notes.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [272, 882, 421, 903], \"page_id\": 8}], \"content\": \"52-Week Bills\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [276, 923, 863, 1368], \"page_id\": 8}], \"content\": \"On January 24 tenders were invited for approximately $4,000 million of 359-day Treasury bills to be dated February 5, 1980, and to mature January 29, 1981. The issue was to refund $3,543 million of bills maturing February 5, and to raise $457 million new cash. Tenders were opened on January 30. They totaled $5,936 million, of which $4,001 million was accepted, including $176 million of noncompetitive tenders from the public and $1,270 million of the bills issued at the average price to Federal Reserve Banks for themselves and as agents for foreign and international monetary authorities. The average bank discount rate was 11.211%.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [276, 1371, 528, 1391], \"page_id\": 8}], \"content\": \"13-Week and 26-Week Bills\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [276, 1407, 859, 1581], \"page_id\": 8}], \"content\": \"Issues of regular weekly Treasury bills in January totaled $32,000 million. These issues were offered for cash and in exchange for bills maturing in the amount of $29,900 million. There were five 13-week issues of $3,200 million and five 26-week issues of $3,200 million. Average rates\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [945, 378, 1215, 396], \"page_id\": 8}], \"content\": \"Department of the Treasury.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [947, 411, 1540, 895], \"page_id\": 8}], \"content\": \"Tenders are received at Federal Reserve banks and branches and from individuals at the Bureau of the Public Debt, Washington. Each tender must be for a minimum of $10,000. Tenders over $10,000 must be in multiples of $5,000. Payment for the full par amount applied for must accompany all tenders submitted for bills to be maintained on the book-entry records of the Department of the Treasury. A cash adjustment will be made for the difference between the par payment submitted and the actual issue price as determined in the auction. No deposit need accompany tenders from incorporated banks and trust companies and from responsible and recognized dealers in investment securities for bills to be maintained on the book-entry records of Federal Reserve Banks and Branches. A deposit of 2 percent of the par amount of the bills applied for must accompany tenders for such bills from others, unless an express guaranty of payment by an incorporated bank or trust company accompanies the tenders.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [949, 939, 1545, 1072], \"page_id\": 8}], \"content\": \"Noncompetitive tenders (without stated price), usually for $500,000 or less from any one bidder, for each issue of 13-week, 26-week, and 52-week bills, are accepted in full at the weighted average price of accepted competitive bids for an issue.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [955, 1093, 1545, 1252], \"page_id\": 8}], \"content\": \"Payment for accepted tenders must be made or completed on the date of issue, in cash or other immediately available funds or in a like par amount of Treasury securities maturing on or before that date. Payment for 13-week, 26-week, and 52-week bills may not be made by credit in Treasury tax and loan accounts.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [959, 1299, 1557, 1322], \"page_id\": 8}], \"content\": \"Nonmarketable Foreign Series Securities - Foreign Governments\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [955, 1337, 1545, 1551], \"page_id\": 8}], \"content\": \"Dollar denominated foreign series securities issued to official institutions in January totaled $1,476 million consisting of 4 bills, 10 certificates, and 1 note. Redemptions during the month totaled $1,418 million. At the end of January, dollar denominated foreign series securities outstanding totaled $23,608 million. (Details are shown on page 61.)\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [949, 1576, 1549, 1759], \"page_id\": 8}], \"content\": \"Nonmarketable Foreign Series Securities - Public Offerings\\nOn January 18 the Treasury announced that it would offer two issues of Deutsche mark (DM) denominated notes in the amount of approximately DM 2 billion for sale by subscription exclusively to residents of the Federal Republic of Germany.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [949, 1772, 1545, 1867], \"page_id\": 8}], \"content\": \"Both issues of notes were made on January 25, 1980, with the 8.50% notes due July 26, 1982, and the 8.45% note due July 26, 1983.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [947, 1885, 1545, 2065], \"page_id\": 8}], \"content\": \"On November 7 the Treasury accepted DM 970 million in subscriptions for its 8.50% 2-year 6-months notes and DM1,050 million for the 8.45% 3-year 6-month notes. The dollar equivalents of the two issues were $561 million of the 8.50% notes and $607 million of the 8.45% notes.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [276, 1597, 786, 1617], \"page_id\": 8}], \"content\": \"for the new issues are shown in the following table.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [278, 1615, 867, 1862], \"page_id\": 8}], \"content\": \"<table><tr><th>Date of issue</th><th colspan=\\\"2\\\">Annual average rate (bank discount basis)</th></tr><tr><th>1980</th><th>13-week</th><th>26-week</th></tr><tr><td>January 3</td><td>12.105</td><td>11.880</td></tr><tr><td>10</td><td>11.944</td><td>11.858</td></tr><tr><td>17</td><td>11.903</td><td>11.783</td></tr><tr><td>24</td><td>12.189</td><td>11.886</td></tr><tr><td>31</td><td>12.038</td><td>11.846</td></tr></table>\", \"description\": null, \"id\": 19, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [272, 1862, 839, 1887], \"page_id\": 8}], \"content\": \"Treasury Bills (Other than Cash management bills) - Gener\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [276, 1895, 867, 2065], \"page_id\": 8}], \"content\": \"Treasury bills are sold on a discount basis under competitive and noncompetitive bidding, and at maturity theirpar amount is payable without interest. All series are issued entirely in book-entry form in a minimum amount of $10,000 and in any higher $5,000 multiple, on the records either of the Federal Reserve Banks and Branches, or of the\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [290, 2088, 955, 2111], \"page_id\": 8}], \"content\": \"Note: Details of figures may not add to totals because of rounding.\", \"description\": null, \"id\": 22, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [219, 103, 499, 147], \"page_id\": 9}], \"content\": \"February 1980\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1571, 95, 1590, 121], \"page_id\": 9}], \"content\": \"1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [702, 167, 1127, 185], \"page_id\": 9}], \"content\": \"FEDERAL FISCAL OPERATIONS\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [599, 219, 1215, 244], \"page_id\": 9}], \"content\": \"Table FFO-1. - Summary of Fiscal Operations\", \"description\": null, \"