description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [179, 331, 742, 430], \"page_id\": 92}], \"content\": \"Table IFS-1 shows the reserve assets of the United States, including its gold stock, special drawing rights held in the Special Drawing Account in the International Monetary Fund, holdings of convertible foreign currencies, and reserve position in the International Monetary Fund.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [179, 435, 740, 514], \"page_id\": 92}], \"content\": \"Table IFS-2 brings together statistics on liabilities to foreign official institutions, and liquid liabilities to all other foreigners, which are used in the United States balance-of-payments statistics.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [935, 241, 1493, 280], \"page_id\": 92}], \"content\": \"Table IFS-3 presents an area breakdown of United States liabilities to official institutions of foreign countries.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [933, 295, 1490, 350], \"page_id\": 92}], \"content\": \"Table IFS-4 shows United States Treasury nonmarketable bonds and notes issued to official institutions and other residents of foreign countries.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [932, 362, 1490, 420], \"page_id\": 92}], \"content\": \"Table IFS-5 sets forth the factors which affect the United States position in the International Monetary Fund.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [933, 439, 1490, 502], \"page_id\": 92}], \"content\": \"Table IFS-6 presents a measure of weighted-average changes in exchange rates between the United States dollar and the currencies of certain other countries.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [597, 596, 1082, 632], \"page_id\": 92}], \"content\": \"Table IFS-1. - U.S. R